/**
 * UserTasks brand mark ("user -> task") and wordmark. A user (cream dot) is
 * connected by a workflow path (down, then a rounded elbow to the right) to a
 * task (the bronze block). Geometry matches public/brand/*.svg, generated by
 * scripts/brand/build-svgs.py.
 */

export const BRAND_COLORS = {
  ink: "#17150F",
  cream: "#FAF8F3",
  bronze: "#C7A575",
  /** Bronze for text and small marks on light backgrounds. */
  bronzeText: "#977443",
} as const

type MarkProps = {
  /** Rendered height in px (the tile is square). */
  size?: number
  /**
   * `tile` — the ink rounded square (default). `glyph` — no tile, for placing
   * the mark directly on a surface; colours come from `color`/`accent`.
   */
  variant?: "tile" | "glyph"
  /** Glyph colours; any CSS colour, including theme variables. */
  color?: string
  accent?: string
  /** Tile colour (variant `tile`). */
  tile?: string
  className?: string
  /** Accessible name; omit when the mark sits next to visible brand text. */
  title?: string
}

function Glyph({ color, accent }: { color: string; accent: string }) {
  return (
    <>
      {/* Colours go through style so CSS variables work (theme-aware marks). */}
      <circle cx="17" cy="17" r="7" style={{ fill: color }} />
      <path d="M17 31v6a8 8 0 0 0 8 8h6" fill="none" strokeWidth="6" strokeLinecap="round" style={{ stroke: color }} />
      <rect x="36" y="36" width="18" height="18" rx="5" style={{ fill: accent }} />
    </>
  )
}

export function LogoMark({ size = 32, variant = "tile", color, accent, tile = BRAND_COLORS.ink, className, title }: MarkProps) {
  const isTile = variant === "tile"
  const a11y = title ? { role: "img", "aria-label": title } : { "aria-hidden": true as const }
  return (
    <svg
      viewBox={isTile ? "0 0 64 64" : "8 8 48 48"}
      height={size}
      width={size}
      className={className}
      style={{ flexShrink: 0 }}
      {...a11y}
    >
      {isTile && <rect width="64" height="64" rx="15" style={{ fill: tile }} />}
      <Glyph
        color={color ?? (isTile ? BRAND_COLORS.cream : BRAND_COLORS.ink)}
        accent={accent ?? (isTile ? BRAND_COLORS.bronze : BRAND_COLORS.bronzeText)}
      />
    </svg>
  )
}

type WordmarkProps = {
  /** `dark` — ink text for light backgrounds; `light` — cream text for dark ones. */
  tone?: "dark" | "light"
  /** Mark height in px; the text scales with it. */
  size?: number
  className?: string
  /** Hide the mark and show the text only. */
  textOnly?: boolean
}

/** Mark + "usertasks" set in the app's DM Sans bold. */
export function Wordmark({ tone = "dark", size = 28, className, textOnly }: WordmarkProps) {
  const light = tone === "light"
  return (
    <span className={`inline-flex items-center font-sans font-bold tracking-tight ${className ?? ""}`} style={{ gap: size * 0.3, lineHeight: 1 }}>
      {!textOnly && (
        <LogoMark
          size={size}
          tile={light ? BRAND_COLORS.cream : BRAND_COLORS.ink}
          color={light ? BRAND_COLORS.ink : BRAND_COLORS.cream}
          accent={light ? BRAND_COLORS.bronzeText : BRAND_COLORS.bronze}
        />
      )}
      <span style={{ fontSize: size * 0.72, color: light ? BRAND_COLORS.cream : BRAND_COLORS.ink }}>
        user<span style={{ color: light ? BRAND_COLORS.bronze : BRAND_COLORS.bronzeText }}>tasks</span>
      </span>
    </span>
  )
}
